function Counter() {
  const [count, setCount] = useState(0);

  function addThree() {
    // All three updaters run in order on the same queued value.
    setCount(c => c + 1);
    setCount(c => c + 1);
    setCount(c => c + 1);
  }

  // A delayed handler would still add one to the newest value.
  function addLater() {
    setTimeout(() => setCount(c => c + 1), 1000);
  }

  return <button onClick={addThree}>{count}</button>;
}

// Data shape: [{ id, name }]
function buildRows() {
  // Pretend this does real work over a large array.
  return Array.from({ length: 5000 }, (_, i) => ({ id: i, name: `Row ${i}` }));
}

function Table() {
  // Wrong: buildRows() runs on every render and the result is thrown away.
  // const [rows] = useState(buildRows());

  // Right: React calls the function once, on mount.
  const [rows] = useState(() => buildRows());

  return <p>{rows.length} rows</p>;
}

function SaveButton() {
