  const [error, setError] = useState(null);
  const [savedAt, setSavedAt] = useState(null);

  function handleSave() {
    setSaving(true);
    setError(null);
    setSavedAt(null);
    // One render when the handler returns, not three.
  }

  async function handleSaveAsync() {
    setSaving(true); // renders here
    await save();
    setSaving(false); // renders again after the await
  }

  return <button onClick={handleSave}>{saving ? 'Saving' : 'Save'}</button>;
}

function Counter() {
  const [count, setCount] = useState(0);

  function handleClick() {
    setCount(count + 1);
    // Still the old number, because this render owns a fixed `count`.
    console.log(count);
  }

  return <button onClick={handleClick}>{count}</button>;
}

// Data shape: { customer_email, first_name, last_name }
function CustomerForm() {
  const [form, setForm] = useState({ customer_email: '', first_name: '', last_name: '' });

  function setField(field, value) {
    // Spread the old object, then override one key.
    setForm(current => ({ ...current, [field]: value }));
  }

  return (
    <input
      value={form.first_name}
      onChange={e => setField('first_name', e.target.value)}
    />
  );
}

